import json
d=json.load(open('ipad.json'))
print('METADATA:', json.dumps(d.get('metadata',{}))[:2000])
print('---')
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        elif o.get('type')=='heading': out.append('\n## '+o.get('text','')+'\n')
        elif o.get('type')=='paragraph':
            walk(o.get('inlineContent',[]),out); out.append('\n\n')
        elif o.get('type')=='reference': out.append('['+str(o.get('identifier',''))+']')
        else:
            for v in o.values(): walk(v,out)
    elif isinstance(o,list):
        for v in o: walk(v,out)
out=[]
walk(d.get('abstract',[]),out); out.append('\n\n')
walk(d.get('primaryContentSections',[]),out)
print(''.join(out))
